from pathlib import Path
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.lib.units import mm
from pypdf import PdfReader
import pandas as pd
ROOT=Path(__file__).resolve().parents[1];E=ROOT/'Code/experiments';OUT=ROOT/'Report/ScaleWave_Magnitude_Forecasting_Framework_48h_4h.pdf'
a=pd.read_csv(E/'two_group_tuning_v1/scores.csv').set_index('model');b=pd.read_csv(E/'five_feature_4h_v1/scores.csv').set_index('model');c=pd.read_csv(E/'seven_eight_feature_4h_v1/scores.csv').set_index('model');d=pd.read_csv(E/'individual_hybrid_additions_v1/individual_results.csv')
s=getSampleStyleSheet();s.add(ParagraphStyle(name='T',parent=s['Title'],fontName='Helvetica-Bold',fontSize=21,leading=25,textColor=colors.HexColor('#17384C'),spaceAfter=6));s.add(ParagraphStyle(name='Sub',parent=s['Normal'],fontSize=9,textColor=colors.HexColor('#567080'),spaceAfter=10));s.add(ParagraphStyle(name='B',parent=s['BodyText'],fontSize=9.5,leading=13,spaceAfter=6));s.add(ParagraphStyle(name='H',parent=s['Heading2'],fontSize=13,leading=16,textColor=colors.HexColor('#087E8B'),spaceBefore=6,spaceAfter=4));s.add(ParagraphStyle(name='Tiny',parent=s['BodyText'],fontSize=8,leading=10,spaceAfter=5))
story=[]
def p(x,sty='B'):story.append(Paragraph(x,s[sty]))
def tab(headers,rows,widths):
 data=[[Paragraph(str(x),s['Tiny']) for x in row] for row in [headers]+rows];t=Table(data,colWidths=widths,repeatRows=1);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#17384C')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.HexColor('#EDF4F6'),colors.white]),('GRID',(0,0),(-1,-1),.25,colors.HexColor('#CDD9DE')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]));story.extend([t,Spacer(1,6)])
def foot(c,d):c.setFont('Helvetica',8);c.setFillColor(colors.HexColor('#567080'));c.drawString(16*mm,10*mm,'ScaleWave | magnitude forecasting');c.drawRightString(194*mm,10*mm,str(d.page))
p('Connecting experiments to a magnitude forecast','T');p('48-hour and 4-hour evidence, and how it fits the framework in the shared photos','Sub')
p('What the photos propose','H');p('Keep three layers clear: <b>research evidence</b> (what past tests measured), a <b>forecast object</b> (model outputs at each timestamp), and a separate <b>decision layer</b> (whether/how to act). The example values in the photos are illustrative. They are not results from our experiments.')
p('What our experiments predict','H');p('The magnitude experiments estimate the absolute BTC endpoint return over a fixed horizon. They estimate movement size, not whether BTC goes up or down. MAE measures average magnitude error in log basis points (lower is better); Spearman IC measures whether larger forecasts tend to line up with larger realized moves (higher is better).')
p('48-hour evidence','H');p('The 48-hour runs use a different target and score scale than the 4-hour runs. The tested magnitude hybrid and MLP results were:')
r=[]
for key,label in [('baseline','Median-regression / RF reference'),('yesterday_best','Volatility-ratio RF candidate'),('mlp_eight','8-feature MLP'),('mlp_seven','7-feature MLP'),('rf_eight','8-feature RF'),('rf_seven','7-feature RF')]:
 z=a.loc[key];r.append([label,f"{z.mae:.3f}",f"{z.rank_ic:.4f}"])
tab(['48h model','MAE (log bps)','Spearman IC'],r,[92*mm,43*mm,35*mm])
p('The best listed 48-hour MAE here is the volatility-ratio RF candidate (181.248); its IC is 0.1068. The 8-feature MLP has MAE 181.462 and IC 0.0839. The original baseline is 181.526 / 0.0774. These historical comparisons do not establish a live probability or a fresh independent confirmation.','Tiny')
p('The 48-hour candidate feature set included the original 5m and 15m peer liquidation activity features and a 4h/24h volatility ratio. The 8-feature study also tested 1h liquidation activity, 168h realized volatility, 1h venue breadth, 5m funding persistence, and 1h basis level. Its RF/MLP variants did not beat the 48-hour reference MAE.','Tiny')
story.append(PageBreak());p('4-hour evidence and forecast design','T');p('Use horizon-specific forecasts and evaluate each horizon against its own baseline. The 4-hour score scale must not be compared directly with the 48-hour score scale.','Sub')
p('4-hour results','H');r=[]
for key,label in [('hybrid_four','Hybrid, 4 features'),('mlp_four','MLP, 4 features'),('hybrid_five','Hybrid, 5 features'),('mlp_five','MLP, 5 features'),('hybrid_seven','Hybrid, 7 features'),('mlp_seven','MLP, 7 features'),('hybrid_eight','Hybrid, 8 features'),('mlp_eight','MLP, 8 features')]:
 frame=b if 'five' in key else c;z=frame.loc[key];r.append([label,f'{z.mae:.4f}',f'{z.rank_ic:.5f}'])
tab(['4h model','MAE (log bps)','Spearman IC'],r,[92*mm,43*mm,35*mm])
p('Among these fixed combinations, 8-feature hybrid has the lowest MAE (50.5001); 5-feature MLP has the highest IC (0.21590). The five-feature input set is the original liquidation 5m/15m pair plus 4h/24h volatility ratio, 1h venue breadth, and 168h realized volatility. The original pair plus ratio and breadth was the four-feature set. Seven features omit 1h activity; eight include it.','Tiny')
p('In the earlier 4-hour individual-addition tests, volatility ratio, venue breadth and 168h realized volatility each improved MAE and IC over the matched two-feature model for both model families. This is conditional evidence from that test design, not a universal feature-importance ranking.','Tiny')
p('How this supports the photo framework','H');tab(['Framework layer','What these experiments can supply','What is still needed'],[['Research evidence','Horizon-specific MAE, rank IC, candidate model, tested inputs, and comparisons with existing references.','Further time/regime breakdowns and fresh confirmation before calling a candidate confirmed.'],['Magnitude forecast','A point estimate of absolute endpoint movement size, with horizon and log-bps units.','Timestamped saved predictions and a calibrated uncertainty/range if one is required.'],['Decision layer','The magnitude estimate can be one input to a separate cost/risk decision process.','The magnitude model alone does not provide up/down probability, calibrated tail probability, position size, or a trade instruction.']],[39*mm,70*mm,62*mm])
p('Suggested magnitude forecast record','H');p('BTC | 4H MAGNITUDE FORECAST<br/>Horizon: 4 hours<br/>Predicted median absolute endpoint move: [model output] log bps<br/>Model / feature set: [model and inputs]<br/>Evidence: MAE [measured score] | Spearman IC [measured score]<br/>Status: [exploratory / development candidate / frozen for fresh confirmation / confirmed]','Tiny')
p('Do not copy the photo’s example values (62% up, 340 log bps, 24% tail probability) into this forecast. Our magnitude runs did not measure direction probabilities or extreme-move probabilities. A magnitude forecast reports size; direction and tail forecasts require their own targets and evaluation.','Tiny')
p('Sources: Code/experiments/two_group_tuning_v1/scores.csv; Code/experiments/five_feature_4h_v1/scores.csv; Code/experiments/seven_eight_feature_4h_v1/scores.csv; Code/experiments/individual_4h_additions_v1/individual_results.csv. The results use previously examined historical evaluation data.','Tiny')
SimpleDocTemplate(str(OUT),pagesize=A4,rightMargin=15*mm,leftMargin=15*mm,topMargin=13*mm,bottomMargin=16*mm,title='ScaleWave Magnitude Forecasting Framework').build(story,onFirstPage=foot,onLaterPages=foot)
rdr=PdfReader(OUT);assert len(rdr.pages)==2, len(rdr.pages);txt=' '.join(x.extract_text() for x in rdr.pages);assert '181.248' in txt and '50.5001' in txt and 'did not measure' in txt and 'extreme-move probabilities' in txt;print(OUT)
